afterEach(function (): void {
    Facade::clearResolvedInstances();
    Container::setInstance(null);
});

it('registers through its service provider and merges its config', function () {
    TestApp::boot();
    expect(config('connectors.microsoft-outlook.mode'))->toBe('auto');
    expect(config('connectors.microsoft-outlook.credentials'))->toBeArray();
});

it('fakes event_get and records it for assertSent', function () {
    TestApp::boot();
    MicrosoftOutlook::fake();
    $config = [
        'id' => 'example-id',
    ];
    $result = MicrosoftOutlook::call('event_get', $config);

    expect($result->mode->value)->toBe('fake');
    MicrosoftOutlook::assertSent('event_get', fn (array $sent): bool => $sent == $config);
    MicrosoftOutlook::assertNotSent('no_such_operation');
    MicrosoftOutlook::assertSentCount(1);
});

it('refuses a forged calendar_changed delivery before the app sees it', function () {
    $app = TestApp::boot();
    $app['router']->microsoftOutlookCalendarChanged('/hooks/microsoft-outlook');
    $response = TestApp::dispatch($app, Request::create('/hooks/microsoft-outlook', 'POST', server: ['CONTENT_TYPE' => 'application/json'], content: '{"forged":true}'));

    expect($response->getStatusCode())->toBe(401);
});
